import { ChevronRightIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { Button } from '@/registry/ndeko/ui/button';

import { ROWS, SECTION } from './data';
import { FeatureMedia } from './feature-media';

function isMediaFirst(index: number) {
  return index % 2 === 1;
}

export default function Features01() {
  return (
    <section className='px-4 py-16 sm:px-6 sm:py-24 lg:px-8'>
      <div className='mx-auto flex max-w-6xl flex-col gap-14 sm:gap-20'>
        <div className='flex max-w-2xl flex-col gap-3'>
          <h2 className='text-2xl font-semibold text-balance sm:text-3xl'>
            {SECTION.title}
          </h2>
          <p className='text-muted-foreground text-base text-pretty'>
            {SECTION.description}
          </p>
        </div>
        <ul className='flex flex-col gap-16 sm:gap-24'>
          {ROWS.map((row, index) => (
            <li
              key={row.id}
              className='grid items-center gap-8 lg:grid-cols-2 lg:gap-16'
            >
              <div className='flex flex-col items-start gap-4'>
                <span className='keycap-3d text-muted-foreground flex size-9 items-center justify-center rounded-lg'>
                  <row.icon />
                </span>
                <h3 className='text-xl font-semibold text-balance'>
                  {row.title}
                </h3>
                <p className='text-muted-foreground max-w-md text-sm leading-relaxed text-pretty'>
                  {row.description}
                </p>
                <Button
                  variant='link'
                  className='h-auto px-0'
                  nativeButton={false}
                  render={<a href='#' />}
                >
                  {row.linkLabel}
                  <ChevronRightIcon className='size-3.5' />
                </Button>
              </div>
              <div className={cn(isMediaFirst(index) && 'lg:order-first')}>
                <FeatureMedia id={row.id} />
              </div>
            </li>
          ))}
        </ul>
      </div>
    </section>
  );
}

import { cn } from '@/registry/ndeko/lib/utils';
import { Chip } from '@/registry/ndeko/ui/chip';
import { StatusOrb } from '@/registry/ndeko/ui/status-orb';

import {
  INVOICE,
  type InvoiceLine,
  type MediaId,
  PAYMENTS,
  REMINDERS,
} from './data';

const AMOUNT_FORMAT = new Intl.NumberFormat('en', {
  style: 'currency',
  currency: 'XXX',
  maximumFractionDigits: 0,
});

const SURFACE =
  'bg-card hairline-ring ring-border dark:bg-foreground/[0.04] rounded-xl shadow-[0_1px_2px_rgb(0_0_0/0.04),0_12px_32px_-16px_rgb(0_0_0/0.12)]';

function amountOf(value: number) {
  return AMOUNT_FORMAT.format(value);
}

function lineTotalOf(line: InvoiceLine) {
  return line.hours * line.rate;
}

function invoiceTotalOf(lines: InvoiceLine[]) {
  let total = 0;
  for (const line of lines) {
    total += lineTotalOf(line);
  }
  return total;
}

function hoursLabelOf(hours: number) {
  if (hours === 1) {
    return '1 hour';
  }
  return `${hours} hours`;
}

function InvoiceMedia() {
  const total = invoiceTotalOf(INVOICE.lines);

  return (
    <div className={cn(SURFACE, 'flex w-full max-w-sm flex-col gap-4 p-5')}>
      <div className='flex items-start justify-between gap-3'>
        <div className='flex flex-col gap-0.5'>
          <p className='text-sm font-medium'>{INVOICE.client}</p>
          <p className='text-muted-foreground text-xs tabular-nums'>
            {INVOICE.number}, {INVOICE.period}
          </p>
        </div>
        <Chip color='var(--muted-foreground)'>{INVOICE.status}</Chip>
      </div>
      <table className='w-full text-[13px]'>
        <caption className='sr-only'>Invoice lines</caption>
        <thead>
          <tr className='text-muted-foreground hairline-b border-border text-xs'>
            <th scope='col' className='pb-2 text-left font-medium'>
              Task
            </th>
            <th scope='col' className='pb-2 text-right font-medium'>
              Amount
            </th>
          </tr>
        </thead>
        <tbody>
          {INVOICE.lines.map((line) => {
            const lineTotal = lineTotalOf(line);

            return (
              <tr
                key={line.description}
                className='hairline-b border-border last:border-b-0'
              >
                <td className='py-2'>
                  <span className='block'>{line.description}</span>
                  <span className='text-muted-foreground text-xs tabular-nums'>
                    {hoursLabelOf(line.hours)} at {amountOf(line.rate)}
                  </span>
                </td>
                <td className='py-2 text-right align-top tabular-nums'>
                  {amountOf(lineTotal)}
                </td>
              </tr>
            );
          })}
        </tbody>
        <tfoot>
          <tr className='hairline-t border-border'>
            <th scope='row' className='pt-3 text-left font-medium'>
              Total
            </th>
            <td className='pt-3 text-right font-semibold tabular-nums'>
              {amountOf(total)}
            </td>
          </tr>
        </tfoot>
      </table>
    </div>
  );
}

function RemindersMedia() {
  return (
    <ol className={cn(SURFACE, 'flex w-full max-w-sm flex-col gap-1 p-2')}>
      {REMINDERS.map((reminder) => (
        <li key={reminder.title} className='flex items-center gap-3 p-2.5'>
          <span className='keycap-3d text-muted-foreground flex size-8 shrink-0 items-center justify-center rounded-lg'>
            <reminder.icon />
          </span>
          <div className='flex min-w-0 flex-1 flex-col'>
            <p className='truncate text-[13px] font-medium'>{reminder.title}</p>
            <p className='text-muted-foreground text-xs'>{reminder.date}</p>
          </div>
          <Chip color={reminder.color}>{reminder.status}</Chip>
        </li>
      ))}
    </ol>
  );
}

function PaymentsMedia() {
  const latest = PAYMENTS[0];

  return (
    <div className='relative w-full max-w-sm pt-10 sm:pt-0'>
      <ul className={cn(SURFACE, 'flex flex-col gap-1 p-2')}>
        {PAYMENTS.map((payment) => (
          <li
            key={payment.invoice}
            className='flex items-center justify-between gap-3 p-2.5'
          >
            <div className='flex min-w-0 flex-col'>
              <p className='truncate text-[13px] font-medium'>
                {payment.client}
              </p>
              <p className='text-muted-foreground text-xs tabular-nums'>
                {payment.invoice}
              </p>
            </div>
            <div className='flex shrink-0 flex-col items-end gap-1'>
              <span className='text-[13px] tabular-nums'>
                {amountOf(payment.amount)}
              </span>
              <Chip color={payment.color}>{payment.status}</Chip>
            </div>
          </li>
        ))}
      </ul>
      <div className='surface-raised absolute -top-2 right-0 flex items-center gap-2.5 rounded-xl py-2 ps-2 pe-3.5 sm:-top-6 sm:-right-4'>
        <StatusOrb tone='success' size='sm' className='[&>span]:animate-none' />
        <p className='text-[13px] font-medium tabular-nums'>
          {amountOf(latest.amount)} received
        </p>
      </div>
    </div>
  );
}

const MEDIA_BY_ID: Record<MediaId, () => React.ReactNode> = {
  invoice: InvoiceMedia,
  reminders: RemindersMedia,
  payments: PaymentsMedia,
};

export function FeatureMedia({ id }: { id: MediaId }) {
  const Media = MEDIA_BY_ID[id];

  return (
    <div
      aria-hidden='true'
      className='bg-foreground/[0.025] flex min-h-72 items-center justify-center rounded-2xl p-4 sm:p-10'
    >
      <Media />
    </div>
  );
}

import {
  BellIcon,
  ClockIcon,
  FileTextIcon,
  type Icon,
  MailIcon,
  SendIcon,
  WalletIcon,
} from '@/registry/ndeko/lib/icons';

export type MediaId = 'invoice' | 'reminders' | 'payments';

export type FeatureRow = {
  id: MediaId;
  icon: Icon;
  title: string;
  description: string;
  linkLabel: string;
};

export const SECTION = {
  title: 'Everything between the last tracked hour and the paid invoice',
  description:
    'Three steps that usually live in three tools, kept in one place and in the right order.',
};

export const ROWS: FeatureRow[] = [
  {
    id: 'invoice',
    icon: FileTextIcon,
    title: 'Draft invoices from the hours you tracked',
    description:
      'Pick a client and a period. Tallyfold groups the time by task, applies each rate and leaves a draft for you to check line by line.',
    linkLabel: 'How drafts work',
  },
  {
    id: 'reminders',
    icon: BellIcon,
    title: 'Reminders that stay polite',
    description:
      'Choose the tone and the rhythm once. Tallyfold follows up on late invoices and stops the moment a payment arrives.',
    linkLabel: 'Set up reminders',
  },
  {
    id: 'payments',
    icon: WalletIcon,
    title: 'Payments land beside the invoice',
    description:
      'Clients pay by card or bank transfer from the link in the email. The invoice turns paid and the books follow the same day.',
    linkLabel: 'See payment options',
  },
];

export type InvoiceLine = {
  description: string;
  hours: number;
  rate: number;
};

export const INVOICE = {
  number: 'TF-0142',
  client: 'Harbor & Finch Studio',
  period: '1 to 31 October',
  status: 'Draft',
  lines: [
    { description: 'Brand workshop', hours: 6, rate: 90 },
    { description: 'Website copy', hours: 14, rate: 75 },
    { description: 'Review rounds', hours: 3, rate: 75 },
  ] satisfies InvoiceLine[],
};

export type Reminder = {
  icon: Icon;
  title: string;
  date: string;
  status: string;
  color: string;
};

export const REMINDERS: Reminder[] = [
  {
    icon: SendIcon,
    title: 'Invoice sent',
    date: 'Mon 3 Nov',
    status: 'Delivered',
    color: 'var(--success)',
  },
  {
    icon: MailIcon,
    title: 'Friendly reminder',
    date: 'Mon 10 Nov',
    status: 'Opened',
    color: 'var(--info)',
  },
  {
    icon: ClockIcon,
    title: 'Second reminder',
    date: 'Mon 17 Nov',
    status: 'Scheduled',
    color: 'var(--warning)',
  },
];

export type Payment = {
  client: string;
  invoice: string;
  amount: number;
  status: string;
  color: string;
};

export const PAYMENTS: Payment[] = [
  {
    client: 'Harbor & Finch Studio',
    invoice: 'TF-0142',
    amount: 1815,
    status: 'Paid',
    color: 'var(--success)',
  },
  {
    client: 'Okafor Bakery',
    invoice: 'TF-0139',
    amount: 640,
    status: 'Paid',
    color: 'var(--success)',
  },
  {
    client: 'Lune Architects',
    invoice: 'TF-0137',
    amount: 2300,
    status: 'Due Friday',
    color: 'var(--warning)',
  },
];
